<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import GameNav from './GameNav.vue'
import SceneObject from './SceneObject.vue'
import { games,gameKey } from './catalog'
import { writeGameSave } from './game-storage'
import { revealGameHint } from './game-activity'
import { puzzleDifficulties,type PuzzleDifficulty } from './puzzle-games'
import { colorNames,colorValues } from './color-sort'
import { pieceNames,tangramConflicts,tangramLayouts,tangramPolygon,type Placement } from './tangram'
import { sokoDirections,sokobanDeadlocks,sokobanMap,sokobanCampaign } from './sokoban'
import { advancePattern,answerPattern,balanceWeight,brainHint,brainStars,drawStroke,edgeKey,findDifference,moveBrainSokoban,moveBrainSort,moveBrainTangram,newBrain,nextBrain,visitSokoban,paintMirror,restoreBrain,strokeRemaining,strokeStarts,strokeSolution,weighBrain,type BrainHint,type BrainId,type BrainRound } from './brain-games'

const props=defineProps<{ gameId: BrainId; storageKey?: string }>()
const key=computed(()=>props.storageKey || gameKey(props.gameId))
function readSave() { try { return restoreBrain(localStorage.getItem(key.value),props.gameId) } catch { return null } }
const save=ref(readSave() || newBrain(props.gameId)), game=computed(()=>games.find(game=>game.id === props.gameId)!)
const round=computed(()=>save.value.round), difficulty=computed(()=>puzzleDifficulties.find(item=>item.id === save.value.difficulty)!)
const tangram=computed(()=>round.value.kind === 'tangram' ? round.value : null)
const soko=computed(()=>round.value.kind === 'sokoban' ? round.value : null)
const pattern=computed(()=>round.value.kind === 'pattern-train' ? round.value : null)
const stroke=computed(()=>round.value.kind === 'one-stroke' ? round.value : null)
const balance=computed(()=>round.value.kind === 'balance-scale' ? round.value : null)
const sort=computed(()=>round.value.kind === 'color-sort' ? round.value : null)
const mirror=computed(()=>round.value.kind === 'mirror-draw' ? round.value : null)
const difference=computed(()=>round.value.kind === 'spot-difference' ? round.value : null)
const map=computed(()=>soko.value ? sokobanMap(soko.value.level) : null)
const question=computed(()=>pattern.value?.questions[pattern.value.index])
const carriages=computed(()=>{if(!question.value)return [];const values=[...question.value.sequence];values.splice(question.value.missing ?? 5,0,pattern.value?.answers[pattern.value.index]!==null ? question.value.answer : '?');return values})
const picked=ref(-1),paint=ref(1),feedback=ref(''),hint=ref<BrainHint|null>(null)
const saveError=ref(false),helpOpen=ref(false),resetOpen=ref(false),targetDifficulty=ref<PuzzleDifficulty>('starter')
const history=ref<BrainRound[]>([])
const tangramErrors=computed(()=>tangram.value ? tangramConflicts(tangram.value) : [])
const usedEdges=computed(()=>stroke.value ? new Set(stroke.value.edges.filter(edge=>!strokeRemaining(stroke.value!).some(other=>edgeKey(...other) === edgeKey(...edge))).map(edge=>edgeKey(...edge))) : new Set<string>())
const strokeNodes=computed(()=>stroke.value ? [...new Set(stroke.value.edges.flat())].sort((a,b)=>a-b) : [])
const axisName=computed(()=>mirror.value?.axis === 'vertical' ? '竖直对称轴' : mirror.value?.axis === 'horizontal' ? '水平对称轴' : '两条对称轴')
const sceneNames={tree:'小树',house:'房子',flower:'花朵',butterfly:'蝴蝶',sun:'太阳',ball:'皮球',bird:'小鸟',fish:'小鱼'}
const rules:Record<BrainId,string[]>={
  tangram:['用两块大三角、一块中三角、两块小三角、正方形和平行四边形，拼满目标轮廓。','先选下面的图块，再点棋盘格子的左上角放置；用方向键微调，按“旋转”转动 90°。','图块不能重叠或超出轮廓。平行四边形可以翻面；入门会显示分块参考线。'],
  sokoban:['把所有木箱推到圆形目标上。一次只走一格，可以推箱子，不能拉箱子。','用方向按钮、键盘方向键或点击相邻格移动。先绕到箱子的后面，再开始推。','不要把箱子推到没有目标的墙角。走错时可以撤回，重新留出路线。'],
  'pattern-train':['看看前面五节车厢，找出图形或数字的变化规律。','从下面四个选项里选择下一项，答题后可以查看规律说明。','有的规律一组一组重复，有的每次增加。挑战关可以把奇偶位置分开观察。'],
  'one-stroke':['依次点击相连的点，一笔走完所有线。每条线只能经过一次，同一个点可以多次经过。','亮起的点可以作为起点。沿着灰线连接，已经经过的线会变蓝。','先想想哪些分支容易被封住。遇到走不通的情况，可以撤回一步。'],
  'balance-scale':['左盘放着标明重量的物品，请在右盘放入砝码，让两边一样重。','点砝码卡片放入，点右盘下方的砝码记录取下；每种砝码数量有限。','左边低说明右盘还轻，右边低说明右盘更重。试着组合不同大小的砝码。'],
  'color-sort':['把同色的色块整理到一根管里。全部色管都装满同一种颜色或为空，就过关。','先选来源管，再选接收管。每次移动最上面的一块，接收管必须为空或顶部同色。','空管可以中转，但容量有限。先归拢同色，再为被挡住的颜色腾出位置。'],
  'mirror-draw':['沿对称轴补全图案，让两边像照镜子一样。挑战关需要同时沿两条轴对称。','带底纹的一侧是已知图案。选择颜色，再点另一侧的格子；填错时可以清除。','对应的格子距离对称轴一样远。先数格子，再比较颜色和位置。'],
  'spot-difference':['比较两幅小花园图，找出颜色或细节不同的位置。','在任意一幅图中点击不同的图案，两边都会出现绿色圆圈。','同一处只算一次。可以按行慢慢观察，不用着急。'],
}
const prompts:Record<BrainId,string>={tangram:'七块小图形，拼出完整的大轮廓。',sokoban:'先给箱子留好路线，再一步一步推到目标。','pattern-train':'跟着小火车找规律，看看下一节车厢是什么。','one-stroke':'想好路线，一笔连接每一条线。','balance-scale':'放一放、算一算，让天平停在中间。','color-sort':'分开混合的颜色，每一管都有自己的颜色。','mirror-draw':'像照镜子一样，把另一侧的图案补完整。','spot-difference':'看看小花园里，哪些图案悄悄变了样。'}
const chapterLevels=computed(()=>sokobanCampaign.slice(['starter','explorer','master'].indexOf(save.value.difficulty)*24,(['starter','explorer','master'].indexOf(save.value.difficulty)+1)*24))
const stage=computed(()=>round.value.stage || 1)
function next(){nextBrain(save.value);history.value=[];clear()}
function visit(stage:number){if(visitSokoban(save.value,stage)){history.value=[];clear()}}
const progress=computed(()=>tangram.value ? `${tangram.value.pieces.filter(piece=>piece.placed).length} / 7 块` : soko.value ? `${soko.value.boxes.filter(box=>map.value!.targets.includes(box)).length} / ${soko.value.boxes.length} 箱` : pattern.value ? `${Math.min(pattern.value.index+1,6)} / 6 题` : stroke.value ? `${Math.max(0,stroke.value.path.length-1)} / ${stroke.value.edges.length} 线` : balance.value ? `${balanceWeight(balance.value)} / ${balance.value.target} 克` : sort.value ? `${sort.value.colors} 种颜色` : mirror.value ? axisName.value : `${difference.value?.found.length} / ${difference.value?.differences.length} 处`)
function clear() { picked.value=-1;hint.value=null;feedback.value='' }
function act<T>(operation:()=>T):T {
  history.value.push(JSON.parse(JSON.stringify(round.value)))
  const result=operation()
  if(!result) history.value.pop()
  else { if(history.value.length>30) history.value.shift();hint.value=null;feedback.value=round.value.finished ? '完成啦！每一步观察和尝试都很有收获。' : '' }
  return result
}
function undo() { const previous=history.value.pop();if(!previous || round.value.finished)return;previous.moves=round.value.moves+1;previous.hints=round.value.hints;save.value.round=previous;clear();feedback.value='已撤回一步，可以换个思路。' }
function giveHint() { hint.value=brainHint(save.value);if(hint.value?.index !== undefined && tangram.value)picked.value=hint.value.index }
function requestReset(id=save.value.difficulty) { if(soko.value && round.value.finished && id===save.value.difficulty && save.value.journey?.completed[id]===24){visit(1);return}targetDifficulty.value=id;resetOpen.value=true }
function reset() { nextBrain(save.value,targetDifficulty.value,targetDifficulty.value===save.value.difficulty && !round.value.finished);history.value=[];clear();resetOpen.value=false }
function polygon(index:number,piece:Placement) { return tangramPolygon(index,piece).map(point=>point.join(',')).join(' ') }
function putPiece(x:number,y:number) { if(!tangram.value || picked.value<0){feedback.value='先选择一块图形，再点棋盘放置。';return}if(!act(()=>moveBrainTangram(save.value,picked.value,{...tangram.value!.pieces[picked.value],x,y,placed:true})))feedback.value='这个位置放不下图块，换个格子或旋转试试。' }
function adjustPiece(dx=0,dy=0,rotate=false,flip=false,remove=false) { if(!tangram.value || picked.value<0)return;const piece=tangram.value.pieces[picked.value];if(!act(()=>moveBrainTangram(save.value,picked.value,{...piece,x:remove?0:piece.x+dx,y:remove?0:piece.y+dy,rotation:rotate?(piece.rotation+1)%4:piece.rotation,flipped:flip?!piece.flipped:piece.flipped,placed:remove?false:piece.placed})))feedback.value='图块不能移出棋盘，换个方向试试。' }
function applyTangramHint() { if(hint.value?.index === undefined || !hint.value.placement)return;const {index,placement}=hint.value;act(()=>moveBrainTangram(save.value,index,placement)) }
function sokoMove(direction:number) { if(!act(()=>moveBrainSokoban(save.value,direction)))feedback.value='前面被挡住了，试着绕到另一侧。' }
function sokoClick(index:number) { if(!soko.value || !map.value)return;const direction=sokoDirections.findIndex(step=>soko.value!.player+step.dx+step.dy*map.value!.width === index);if(direction>=0)sokoMove(direction);else feedback.value='一次走相邻的一格，也可以用下方方向按钮。' }
function sokoKeyboard(event:KeyboardEvent) { const direction=['ArrowUp','ArrowRight','ArrowDown','ArrowLeft'].indexOf(event.key);if(direction>=0){event.preventDefault();sokoMove(direction)} }
function choosePattern(answer:string) {
  const result=act(()=>{const correct=answerPattern(save.value,answer);return correct===null?null:{correct}})
  if(result)feedback.value=result.correct?'找对规律啦！':'再看看规律说明，下次会更熟练。'
}
function chooseNode(node:number) { if(!act(()=>drawStroke(save.value,node)))feedback.value='选择相连且还没经过的线；每条线只能走一次。';else if(stroke.value && !stroke.value.finished && !strokeSolution(stroke.value))feedback.value='这一步把剩余路线分开了，可以撤回一步，先走另一条分支。' }
function chooseTube(index:number) { if(!sort.value)return;if(picked.value<0 || picked.value === index){if(!sort.value.tubes[index].length){feedback.value='先选一根有色块的管。';return}picked.value=picked.value===index?-1:index;feedback.value='再选一根接收管。';return}if(act(()=>moveBrainSort(save.value,picked.value,index)))picked.value=-1;else feedback.value='接收管需要有空位，且顶部同色或为空。' }
function chooseDifference(index:number) { const result=act(()=>findDifference(save.value,index));if(result==='same')feedback.value='这里两边一样，再比较其他细节。';else if(result==='found' && !round.value.finished)feedback.value='发现一处不同！继续看看下一处。' }
function nodePosition(node:number) { const size=stroke.value!.size;return {left:`${(node%size+.5)/size*100}%`,top:`${(Math.floor(node/size)+.5)/size*100}%`} }
function mirrorClasses(index:number) { const value=mirror.value!,middle=Math.floor(value.size/2);return {given:value.fixed.includes(index),hinted:hint.value?.index===index,'axis-column':value.axis!=='horizontal' && index%value.size===middle,'axis-row':value.axis!=='vertical' && Math.floor(index/value.size)===middle} }
watch(save,value=>{try{writeGameSave(key.value,value);saveError.value=false}catch{saveError.value=true}},{deep:true,immediate:true,flush:'post'})
watch(key,()=>{save.value=readSave() || newBrain(props.gameId);history.value=[];clear()})
watch(hint,value=>{if(value)void revealGameHint()})

</script>

<template>
  <div :class="['puzzle-play','brain-play',gameId]">
    <GameNav :active="gameId" />
    <main class="puzzle-content">
      <header class="puzzle-heading"><div><span class="puzzle-kicker">益智乐园 · {{ game.skills }}</span><h1>{{ game.title }}<span>.</span></h1><p>{{ prompts[gameId] }}</p></div><div class="puzzle-tools"><div class="puzzle-difficulties" role="group" aria-label="游戏难度"><button v-for="item in puzzleDifficulties" :key="item.id" :class="{active:item.id===save.difficulty}" :aria-pressed="item.id===save.difficulty" @click="item.id!==save.difficulty && requestReset(item.id)">{{ item.name }}</button></div><button class="help-button" aria-label="怎么玩" @click="helpOpen=true"><UIcon name="i-lucide-circle-help" /></button></div></header>
      <section class="puzzle-stats" aria-label="游戏进度"><span><UIcon :name="game.icon" /><strong>{{ difficulty.name }}</strong><small>{{ progress }}</small></span><span>尝试步数<strong>{{ round.moves }}</strong></span><span>已完成<strong>{{ save.rounds }} 局</strong></span><span class="best-stars" :aria-label="`当前难度最佳 ${save.best[save.difficulty]} 颗星`"><UIcon v-for="n in 3" :key="n" name="i-lucide-star" :class="{earned:n<=save.best[save.difficulty]}" /></span></section>
      <p v-if="saveError" class="puzzle-notice" role="alert">浏览器暂时无法保存进度，本局仍可继续。</p>
      <details v-if="soko" class="soko-journey" aria-label="仓库闯关路线"><summary><strong>第 {{ ['starter','explorer','master'].indexOf(save.difficulty)+1 }} 章 · {{ ['转角与双箱','窄道与调度','多箱与规划'][['starter','explorer','master'].indexOf(save.difficulty)] }}</strong><span>24 张不同地图 · {{ soko.level<9?'原有进度，通关后进入新仓库':'当前第 '+((soko.level-9)%24+1)+' 关' }}</span></summary><div class="soko-levels"><button v-for="(item,index) in chapterLevels" :key="item.name" :aria-label="`仓库第 ${index+1} 关 ${item.name}`" :disabled="index>(save.journey?.completed[save.difficulty] || 0)" :class="{current:soko.level===9+['starter','explorer','master'].indexOf(save.difficulty)*24+index,cleared:index<(save.journey?.completed[save.difficulty] || 0)}" @click="visit(index+1)">{{ index<(save.journey?.completed[save.difficulty] || 0)?'✓':index+1 }}</button></div></details><p class="challenge-stage"><template v-if="soko && !round.finished && soko.level>=9 && (soko.level-9)%24<(save.journey?.completed[save.difficulty] || 0)">回顾已通关地图 · </template>{{ soko?(sokobanCampaign[soko.level-9]?.name || '原有仓库进度'):`连续挑战 · 第 ${stage} 关` }}<template v-if="soko && sokobanCampaign[soko.level-9]"> · 推动 {{ soko.pushes || 0 }} 次 · 最少 {{ sokobanCampaign[soko.level-9].pushes }} 次</template></p><div class="puzzle-layout">
        <section class="puzzle-stage" :aria-label="`${game.title}棋盘`"><div class="stage-top"><span>{{ progress }}</span><span>{{ round.finished?'已完成':'慢慢想，不用赶' }}</span></div>
          <template v-if="tangram">
            <div class="tangram-canvas"><svg viewBox="0 0 8 8" aria-hidden="true"><defs><pattern id="tangram-grid" width="1" height="1" patternUnits="userSpaceOnUse"><path d="M1 0H0V1" fill="none" stroke="#dbe3d2" stroke-width=".025" /></pattern></defs><rect width="8" height="8" fill="url(#tangram-grid)" /><polygon :points="tangramLayouts[tangram.layout].outline.map(point=>point.join(',')).join(' ')" fill="#dce5d1" stroke="#a8b89a" stroke-width=".035" /><g v-if="save.difficulty==='starter'"><polygon v-for="(piece,index) in tangramLayouts[tangram.layout].solution" :key="index" :points="polygon(index,piece)" fill="none" stroke="#b3bea5" stroke-width=".045" stroke-dasharray=".08 .06" /></g><template v-for="(piece,index) in tangram.pieces" :key="index"><polygon v-if="piece.placed" :points="polygon(index,piece)" :fill="colorValues[index%6]" :stroke="tangramErrors.includes(index)?'#c66d66':picked===index?'#8d6c34':'#ffffff'" stroke-width=".06" fill-opacity=".92" /></template><polygon v-if="hint?.placement && hint.index!==undefined" :points="polygon(hint.index,hint.placement)" fill="#f6db8b55" stroke="#b69343" stroke-width=".06" stroke-dasharray=".12 .08" /></svg><div class="tangram-hit-grid"><button v-for="n in 64" :key="n" :data-anchor="n-1" :aria-label="`放到第 ${Math.floor((n-1)/8)+1} 行第 ${(n-1)%8+1} 列`" :disabled="round.finished" @click="putPiece((n-1)%8,Math.floor((n-1)/8))" /></div></div>
            <p class="brain-caption">目标：{{ tangramLayouts[tangram.layout].name }} · 选图块，再点格子放置</p>
            <div class="tangram-pieces" role="group" aria-label="七巧板图块"><button v-for="(piece,index) in tangram.pieces" :key="index" :class="{selected:picked===index}" :aria-pressed="picked===index" :aria-label="`选择${pieceNames[index]}`" :disabled="round.finished" @click="picked=index"><svg viewBox="0 0 4 4" aria-hidden="true"><polygon :points="polygon(index,{...piece,x:0,y:0})" :fill="colorValues[index%6]" /></svg><small>{{ index+1 }} · {{ pieceNames[index] }}</small><span v-if="piece.placed" class="placed-tick">✓</span></button></div>
            <div class="piece-controls" role="group" aria-label="调整图块"><button v-for="(move,index) in [[0,-1],[1,0],[0,1],[-1,0]]" :key="index" :aria-label="`图块向${sokoDirections[index].name}移一格`" :disabled="picked<0 || round.finished" @click="adjustPiece(move[0],move[1])">{{ ['↑','→','↓','←'][index] }}</button><button :disabled="picked<0 || round.finished" @click="adjustPiece(0,0,true)">旋转</button><button :disabled="picked!==6 || round.finished" @click="adjustPiece(0,0,false,true)">翻面</button><button :disabled="picked<0 || round.finished" @click="adjustPiece(0,0,false,false,true)">取下</button></div><p v-if="tangramErrors.length" class="conflict-note" role="status">红色边框处有重叠或超出轮廓，可以继续调整。</p>
          </template>
          <template v-else-if="soko && map"><div class="soko-board" :style="{gridTemplateColumns:`repeat(${map.width},minmax(0,1fr))`}" tabindex="0" role="group" aria-label="推箱子方向控制" @keydown="sokoKeyboard"><button v-for="n in map.width*map.height" :key="n" :data-soko="n-1" :class="['soko-cell',{wall:map.walls.includes(n-1),target:map.targets.includes(n-1),box:soko.boxes.includes(n-1),player:soko.player===n-1}]" :disabled="round.finished || map.walls.includes(n-1)" :aria-label="`第 ${Math.floor((n-1)/map.width)+1} 行第 ${(n-1)%map.width+1} 列${soko.boxes.includes(n-1)?'，箱子':soko.player===n-1?'，小店员':map.targets.includes(n-1)?'，目标':''}`" @click="sokoClick(n-1)"><span v-if="soko.boxes.includes(n-1)" class="wood-box" aria-hidden="true">×</span><UIcon v-else-if="soko.player===n-1" name="i-lucide-smile" aria-hidden="true" /><span v-else-if="map.targets.includes(n-1)" class="soko-goal" aria-hidden="true" /></button></div><div class="soko-dpad" @keydown="sokoKeyboard"><button v-for="(direction,index) in sokoDirections" :key="direction.name" :class="`direction-${index}`" :aria-label="`向${direction.name}走`" :disabled="round.finished" @click="sokoMove(index)">{{ ['↑','→','↓','←'][index] }}</button></div><p v-if="sokobanDeadlocks(soko).length" class="conflict-note" role="status">有箱子进入无法推回目标的位置，撤回几步再试试。</p></template>
          <template v-else-if="pattern && question"><div class="pattern-carriages"><span v-for="(token,index) in carriages" :key="index" :class="['train-token',{'symbol-token':['●','▲','■','◆'].includes(token)}]">{{ token }}</span></div><h2 class="brain-question">缺少的这节车厢是什么？</h2><div class="pattern-options"><button v-for="option in question.options" :key="option" :aria-label="`选择下一项 ${option}`" :class="{correct:pattern.answers[pattern.index]!==null && option===question.answer,wrong:pattern.answers[pattern.index]===option && option!==question.answer}" :disabled="pattern.answers[pattern.index]!==null" @click="choosePattern(option)">{{ option }}</button></div><div v-if="pattern.answers[pattern.index]!==null" class="pattern-explanation" role="status" aria-label="规律说明"><p>{{ question.explanation }}</p><button class="primary-button" @click="act(()=>advancePattern(save))">{{ pattern.index===5?'查看结果':'下一题' }}<UIcon name="i-lucide-arrow-right" /></button></div></template>
          <template v-else-if="stroke"><div class="stroke-board"><svg viewBox="0 0 100 100" aria-hidden="true"><line v-for="[a,b] in stroke.edges" :key="edgeKey(a,b)" :x1="(a%stroke.size+.5)/stroke.size*100" :y1="(Math.floor(a/stroke.size)+.5)/stroke.size*100" :x2="(b%stroke.size+.5)/stroke.size*100" :y2="(Math.floor(b/stroke.size)+.5)/stroke.size*100" :class="{used:usedEdges.has(edgeKey(a,b))}" /></svg><button v-for="node in strokeNodes" :key="node" :data-node="node" :style="nodePosition(node)" :class="{current:stroke.path.at(-1)===node,start:!stroke.path.length && strokeStarts(stroke).includes(node),hinted:hint?.index===node}" :aria-label="`连接第 ${node+1} 个点`" :disabled="round.finished" @click="chooseNode(node)">{{ node+1 }}</button></div><p class="brain-caption">蓝线是已走过的路线，同一个点可以再次经过。</p></template>
          <template v-else-if="balance"><div class="scale-scene"><svg viewBox="0 0 400 235" aria-hidden="true"><path d="M180 205L200 75L220 205Z" fill="#97ab91" /><rect x="139" y="202" width="122" height="15" rx="7" fill="#6d8c76" /><g :transform="`rotate(${Math.max(-12,Math.min(12,(balanceWeight(balance)-balance.target)*2))} 200 75)`"><path d="M70 75H330" stroke="#b59972" stroke-width="10" stroke-linecap="round" /><path d="M70 78L40 153M70 78L100 153M330 78L300 153M330 78L360 153" stroke="#bda98b" stroke-width="3" /><path d="M28 153H111Q102 183 70 183Q39 183 28 153M288 153H371Q361 183 330 183Q298 183 288 153" fill="#c7d5bd" /><circle cx="61" cy="133" r="13" fill="#d99077" /><circle cx="80" cy="131" r="15" fill="#d9b66b" /><rect x="312" y="124" width="36" height="27" rx="5" fill="#7ba8b5" /><text x="70" y="196" text-anchor="middle">{{ balance.target }} 克</text><text x="330" y="196" text-anchor="middle">{{ balanceWeight(balance) }} 克</text></g><circle cx="200" cy="75" r="10" fill="#e0c392" /></svg></div><p class="brain-caption">左盘 {{ balance.target }} 克 · 右盘 {{ balanceWeight(balance) }} 克</p><p v-if="balance.maxPieces" class="brain-caption">挑战要求：最多 {{ balance.maxPieces }} 个砝码 · 已放 {{ balance.counts.reduce((a,b)=>a+b,0) }} 个</p><p v-if="balance.maxPieces && balanceWeight(balance)===balance.target && balance.counts.reduce((a,b)=>a+b,0)>balance.maxPieces" class="conflict-note" role="status">重量对了！试着用大砝码换下几个小砝码，减少总个数。</p><div class="weight-tray"><button v-for="(weight,index) in balance.weights" :key="weight" :data-weight="index" :class="{hinted:hint?.index===index && hint.action==='add'}" :aria-label="`放入 ${weight} 克砝码`" :disabled="round.finished || balance.counts[index]>=balance.supply[index]" @click="act(()=>weighBrain(save,index,1))"><span class="weight-icon">{{ weight }}</span><strong>{{ weight }} 克</strong><small>还剩 {{ balance.supply[index]-balance.counts[index] }} 个</small></button></div><div class="selected-weights" aria-label="右盘砝码"><template v-for="(weight,index) in balance.weights" :key="weight"><button v-if="balance.counts[index]" :class="{hinted:hint?.index===index && hint.action==='remove'}" :aria-label="`取下 ${weight} 克砝码`" :disabled="round.finished" @click="act(()=>weighBrain(save,index,-1))">{{ weight }} 克 × {{ balance.counts[index] }}<span aria-hidden="true">−</span></button></template></div></template>
          <template v-else-if="sort"><div class="sort-tubes"><button v-for="(tube,index) in sort.tubes" :key="index" :data-tube="index" :class="{selected:picked===index,hinted:hint?.index===index || hint?.next===index}" :aria-pressed="picked===index" :aria-label="`第 ${index+1} 管，${tube.length} 个色块${tube.length?'，顶部'+colorNames[tube.at(-1)!]:''}`" :disabled="round.finished" @click="chooseTube(index)"><span class="tube-label">{{ index+1 }}</span><span class="tube-glass" :style="{height:`${sort.capacity*32+14}px`}"><span v-for="(color,order) in tube" :key="order" class="color-block" :style="{background:colorValues[color]}">{{ ['●','▲','■','◆','★','♥'][color] }}</span></span></button></div><p class="brain-caption">先选来源管，再选择接收管；每次移动顶部一块。</p></template>
          <template v-else-if="mirror"><p class="brain-caption">{{ axisName }} · 沿轴数一数，找到对应格</p><div class="mirror-board" :style="{gridTemplateColumns:`repeat(${mirror.size},minmax(0,1fr))`}"><button v-for="(cell,index) in mirror.cells" :key="index" :data-mirror="index" :class="['mirror-cell',mirrorClasses(index)]" :style="{background:cell?colorValues[cell-1]:undefined}" :aria-label="`第 ${Math.floor(index/mirror.size)+1} 行第 ${index%mirror.size+1} 列，${cell?colorNames[cell-1]:'空白'}${mirror.fixed.includes(index)?'，已知图案':''}`" :disabled="round.finished || mirror.fixed.includes(index)" @click="act(()=>paintMirror(save,index,paint))">{{ cell?['●','▲','■','◆'][cell-1]:'' }}</button></div><div class="mirror-palette" role="group" aria-label="镜面对称颜色"><button v-for="color in mirror.colors" :key="color" :aria-label="`选择${colorNames[color-1]}`" :aria-pressed="paint===color" :class="{selected:paint===color}" :disabled="round.finished" @click="paint=color"><span :style="{background:colorValues[color-1]}">{{ ['●','▲','■','◆'][color-1] }}</span>{{ colorNames[color-1] }}</button><button :aria-pressed="paint===0" :class="{selected:paint===0}" :disabled="round.finished" @click="paint=0"><UIcon name="i-lucide-eraser" />清除</button></div></template>
          <template v-else-if="difference"><div class="difference-pictures"><section v-for="(items,side) in [difference.left,difference.right]" :key="side" :aria-label="side?'右图':'左图'"><h2>{{ side?'右图':'左图' }}<span>找出 {{ difference.differences.length }} 处不同</span></h2><div class="difference-scene" :style="{gridTemplateColumns:`repeat(${difference.columns},minmax(0,1fr))`}"><button v-for="(item,index) in items" :key="index" :data-spot="index" :class="{found:difference.found.includes(index),hinted:hint?.index===index}" :aria-label="`${side?'右':'左'}图第 ${index+1} 个${sceneNames[item.kind]}`" :disabled="round.finished || difference.found.includes(index)" @click="chooseDifference(index)"><SceneObject :item="item" /><span v-if="difference.found.includes(index)" class="difference-tick" aria-hidden="true">✓</span></button></div></section></div></template>
          <div v-if="round.finished" class="puzzle-success" role="status" aria-label="过关反馈"><div class="success-stars" :aria-label="`本局获得 ${brainStars(round)} 颗星`"><UIcon v-for="n in brainStars(round)" :key="n" name="i-lucide-star" /></div><h2>你解开了这个小挑战！</h2><p>{{ round.moves }} 次尝试，每一步都有收获。</p><p v-if="soko && save.difficulty==='master' && (stage===24 || soko.level===80)">三章仓库挑战全部完成！可以回顾地图，用更少推动赢取三星。</p><button v-if="soko && save.difficulty==='master' && (stage===24 || soko.level===80)" class="primary-button" @click="visit(1)">回顾第 1 关<UIcon name="i-lucide-rotate-ccw" /></button><button v-else class="primary-button" @click="next">{{ soko && (save.journey?.completed[save.difficulty] || 0)>=24 && save.difficulty!=='master'?'前往下一章':'前往下一关' }}<UIcon name="i-lucide-arrow-right" /></button></div>
          <p class="puzzle-feedback" role="status" aria-label="操作反馈">{{ feedback }}</p>
        </section>
        <aside class="puzzle-sidebar"><div class="thinking-card"><span class="sidebar-kicker"><UIcon name="i-lucide-lightbulb" />动动脑筋</span><h2>先观察，再试一试。</h2><p v-for="(rule,index) in rules[gameId]" :key="rule"><span class="rule-number">{{ index+1 }}</span>{{ rule }}</p></div><div v-if="hint && !round.finished" class="hint-card" role="status" aria-label="游戏提示"><strong><UIcon name="i-lucide-sparkles" />给你一点线索</strong><p>{{ hint.text }}</p><button v-if="tangram && hint.placement" class="hint-apply" @click="applyTangramHint">试着按线索摆这一块</button></div><div class="board-tools"><button :disabled="round.finished" @click="giveHint"><UIcon name="i-lucide-lightbulb" />给我提示</button><button :disabled="!history.length || round.finished" @click="undo"><UIcon name="i-lucide-undo-2" />撤回一步</button><button @click="requestReset()"><UIcon name="i-lucide-refresh-cw" />重新开始</button></div><p class="puzzle-footnote"><UIcon name="i-lucide-leaf" />没有倒计时，想一想、歇一歇都可以。</p></aside>
      </div>
    </main>
    <UModal v-model:open="helpOpen" :title="`${game.title}怎么玩`" description="按照自己的节奏，慢慢探索。"><template #body><ol class="help-rules"><li v-for="rule in rules[gameId]" :key="rule">{{ rule }}</li></ol></template><template #footer><button class="primary-button" @click="helpOpen=false">知道啦</button></template></UModal>
    <UModal v-model:open="resetOpen" :title="targetDifficulty===save.difficulty?'重新开始这一局？':`切换到${puzzleDifficulties.find(item=>item.id===targetDifficulty)?.name}？`" description="重试会保留本关布局；切换难度会进入该路线。已完成关卡和星星保留。"><template #footer><button class="secondary-button" @click="resetOpen=false">继续当前游戏</button><button class="primary-button" @click="reset">{{ targetDifficulty===save.difficulty && !round.finished?'重试本关':'开始新挑战' }}</button></template></UModal>
  </div>
</template>
